请对以下 case 进行三维加权评分。

=== case_id ===
Case-10-rainy-taxi-002

=== 用户原始指令 (query.txt) ===
弄个能跳到应用里的，能看天气，看到红色那种危险天气提示

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "弄个能跳到应用里的，能看天气，看到红色那种危险天气提示",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "当前天气查询的区县或位置名称",
            "sampleValue": "本地"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前摄氏温度展示文本",
            "sampleValue": "29°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象",
            "sampleValue": "暴雨"
          },
          "alertLevel": {
            "type": "string",
            "description": "当前最高天气预警等级或预警提示",
            "sampleValue": "红色预警"
          }
        },
        "daily": [
          {
            "rainProbabilityPercent": {
              "type": "string",
              "description": "今天白天降雨概率百分比",
              "sampleValue": "88%"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/rain.png",
      "description": "彩色云朵和雨滴天气图标，适合表示雨天、降雨天气和出行天气状态。"
    }
  ]
}

